// 首history裁剪后唯一旧同tick源也不得换挂；多个本半日完成保持同一真实提交。
#include "resident/domains/family/birth_care_cached_revision.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool yes,const char* text){++checks;if(!yes)throw std::runtime_error(text);}}
int main(){try{CommonState seed;seed.identity.revision=9;seed.identity.tick=4;CommonStore c(seed,std::make_shared<CommonCatalog>());FamilyBirthState births;BirthReply reply;reply.tick=4;reply.revision=6;births.replies.insert("family_birth:2",reply);auto actual=std::make_shared<CommitResult>();actual->result_id="result:3";actual->revision=7;actual->tick=4;c.state().results.insert("actor:1",actual);check(birth_care_cache::birth_revision(c,births,*actual,"family_birth:2").ok,"actual original birth result revision matches");auto later=std::make_shared<CommitResult>();later->result_id="result:8";later->revision=9;later->tick=4;c.state().results.insert("actor:2",later);check(!birth_care_cache::birth_revision(c,births,*later,"family_birth:2").ok,"sole old source cannot fill first retained same-tick later cache");auto copy=*actual;check(!birth_care_cache::birth_revision(c,births,copy,"family_birth:2").ok,"copied shell cannot replace actual cached object");ChildCareReceipt care;care.revision=8;care.tick=4;births.care.insert("family_birth:6",care);births.care.insert("family_birth:7",care);check(birth_care_cache::birth_revision(c,births,*later,"family_birth:6").ok&&birth_care_cache::birth_revision(c,births,*later,"family_birth:7").ok,"two actual Advance care facts share one commit");ChildCareReliefState relief;ChildCareReliefAgreement agreement;agreement.source.revision=6;relief.agreements.insert("family_care_relief:2",agreement);check(birth_care_cache::relief_revision(c,relief,*actual,"family_care_relief:2").ok&&!birth_care_cache::relief_revision(c,relief,*later,"family_care_relief:2").ok,"relief first cache uses same permanent source revision gate");auto duplicate=std::make_shared<CommitResult>(*actual);duplicate->result_id="result:20";c.state().results.insert("actor:3",duplicate);check(!birth_care_cache::birth_revision(c,births,*actual,"family_birth:2").ok,"two cached results cannot claim same actual revision");check(c.state().history.empty()&&births.replies.find("family_birth:2")->revision==6,"guard never repairs or rewrites old history/source");std::cout<<"BIRTH_CARE_CACHED_REVISION "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
